        m = out
    return m

def fill_holes(m):
    # flood from border on ~m; unfilled background inside = hole
    from collections import deque
    H,W = m.shape
    bg = ~m
    seen = np.zeros_like(bg)
    q = deque()
    for x in range(W):
        for y in (0, H-1):
            if bg[y,x] and not seen[y,x]:
                seen[y,x]=1; q.append((y,x))
    for y in range(H):
